info.description:
Theme oscuro con fondo animado estilo Gasterbody {
  background-image: url("PEGA_ACA_TU_GIF.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  background-attachment: fixed;
}

/* Oscurecer la página para que resalte el GIF */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.65);
  pointer-events: none;
  z-index: -1;
}

style.css:
body {
  background-image: url("https://i.pinimg.com/originals/87/22/3a/87223a16be5f2e86d22a8030a37f9a15.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  background-attachment: fixed;
  background-color: black;
}

/* Oscurece la página y hace que el GIF destaque */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.7);
  pointer-events: none;
  z-index: -1;
}
